#define PV(s) ((unsigned char)((s) * 37 + 11))

static void verify(int s, size_t cnt)
{
    for (size_t i = 0; i < cnt; i++)
        if (P[s][i] != PV(s)) {
            printf("corrupt slot %d byte %zu\n", s, i);
            return;
        }
}

int main(void)
{
    unsigned char STACK_BUF[64];
    memset(STACK_BUF, 0, sizeof STACK_BUF);
    size_t nops = sizeof OPS / sizeof OPS[0];
    for (size_t k = 0; k < nops; k++) {
        int op = (int)OPS[k][0];
        int s = (int)OPS[k][1];
        long long a = OPS[k][2], b = OPS[k][3];
        unsigned char *q;
        switch (op) {
        case MALLOC:
            P[s] = my_malloc((size_t)a);
            if (!P[s]) {
                printf("malloc NULL\n");
                break;
            }
            N[s] = (size_t)a;
            memset(P[s], PV(s), N[s]);
            break;
        case CALLOC:
            P[s] = my_calloc((size_t)a, (size_t)b);
            if (!P[s]) {
                printf("calloc NULL\n");
                break;
            }
            N[s] = (size_t)a * (size_t)b;
            for (size_t i = 0; i < N[s]; i++)
                if (P[s][i]) {
                    printf("calloc not zeroed\n");
                    break;
                }
            memset(P[s], PV(s), N[s]);
            break;
        case REALLOC:
            verify(s, N[s]);
            q = my_realloc(P[s], (size_t)a);
            if (!q) {
                printf("realloc NULL\n");
                break;
            }
            P[s] = q;
            verify(s, N[s] < (size_t)a ? N[s] : (size_t)a);
            N[s] = (size_t)a;
            memset(P[s], PV(s), N[s]);
            break;
        case REALLOC_NULL:
            P[s] = my_realloc(NULL, (size_t)a);
            if (!P[s]) {
                printf("realloc NULL\n");
                break;
            }
            N[s] = (size_t)a;
            memset(P[s], PV(s), N[s]);
            break;
        case FREE:
            verify(s, N[s]);
            my_free(P[s]);
            break;
        case FREE_NULL:
            my_free(NULL);
            break;
        case FREE_RAW:
            my_free((unsigned char *)((uintptr_t)P[s] + (uintptr_t)a));
            break;
        case REALLOC_RAW:
            q = my_realloc((unsigned char *)((uintptr_t)P[s] + (uintptr_t)a), (size_t)b);
            printf("bad realloc %s\n", q ? "ptr" : "NULL");
            break;
        case FREE_EXT:
            my_free(s ? (void *)(STATIC_BUF + 64) : (void *)(STACK_BUF + 16));
            break;
        case REALLOC_EXT:
            q = my_realloc(s ? (void *)(STATIC_BUF + 64) : (void *)(STACK_BUF + 16), (size_t)a);
            printf("bad realloc %s\n", q ? "ptr" : "NULL");
            break;
        case COPY:
            P[s] = P[a];
            N[s] = N[a];
            break;
        case POLICY:
            my_set_policy(s);
            break;
        case DELAY:
            my_set_delay(s);
            break;
        case DUMP:
            my_heap_dump();
            break;
        case LEAK:
            my_leak_report();
            break;
        case GUARD:
            P[s][N[s] + (size_t)a] = 0x11;
            break;
        case WAF:
            P[s][a] = (unsigned char)b;
            break;
        case MARK:
            printf("-- %d\n", s);
            break;
        }
    }
    return 0;
}
